// DEV_RIO_704 他媒体リパーパス【下書き準備のみ・dry-run】。
// DEV_RIO_103 の出力(note_body/threads_post/theme/qa_status)を受け取り、
// 他フォーマット向けの下書きを生成する。★自動投稿・自動展開はしない（CLAUDE.md準拠）。
// qa_status が無い手動テスト時は 'PASS' 扱い。
const i = $input.first().json;
return [{ json: {
  content_id: i.content_id ?? 'ca-repurpose-001',
  theme: i.theme ?? '（テーマ未設定）',
  note_body: i.note_body ?? i.note_draft_body ?? '',
  threads_post: i.threads_post ?? '',
  qa_status: i.qa_status ?? 'PASS',
  action_type: 'prepare_repurpose_drafts'
} }];

// リパーパス下書き生成プロンプトを Anthropic body オブジェクトとして組み立てる。
// 対象フォーマット: instagram_caption / short_video_script / substack_intro。
const i = $input.first().json;
const excerpt = String(i.note_body || '').slice(0, 600);
const prompt = `以下の記事を、他媒体向けに『リパーパス』した下書きを作成してください。投稿はせず下書きのみ。

テーマ: ${i.theme}
元記事(note)抜粋: ${excerpt}
元Threads投稿: ${i.threads_post}

次の3フォーマットを各1案、日本語で:
- instagram_caption: Instagram用キャプション(絵文字可・ハッシュタグ3〜5)
- short_video_script: 60秒ショート動画の台本(フック→本編3点→CTAの構成・ナレーション文のみ)
- substack_intro: Substackニュースレターの導入文(3〜4文)

注意: 誇張・虚偽の数値・断定的な成果保証は禁止。元記事にない事実を創作しない。
出力は次のJSON配列のみ（前後に説明・コードブロック記号を付けない）:
[{"format":"instagram_caption","text":"string"},{"format":"short_video_script","text":"string"},{"format":"substack_intro","text":"string"}]`;
const anthropic_body = {
  model: 'claude-haiku-4-5',
  max_tokens: 2048,
  messages: [ { role: 'user', content: prompt } ]
};
return [{ json: { ...i, anthropic_body } }];

// Claude応答をパース。失敗時は捏造せず parse_error を明示。公開直前で停止。
const input = $input.first().json;
const ctx = $('Collect Inputs').first().json;
let drafts = [];
let parse_error = null;
if (input.error) {
  parse_error = 'anthropic_api_error: ' + JSON.stringify(input.error).slice(0, 300);
} else {
  try {
    const text = input.content && input.content[0] && input.content[0].text;
    if (!text) throw new Error('no text in response');
    const cleaned = text.trim().replace(/^```json\s*/i, '').replace(/```\s*$/, '');
    const match = cleaned.match(/\[[\s\S]*\]/);
    drafts = JSON.parse(match ? match[0] : cleaned);
    if (!Array.isArray(drafts) || drafts.length === 0) throw new Error('drafts missing/empty');
    drafts = drafts.map(d => ({ format: d.format ?? 'unknown', text: d.text ?? '' }));
  } catch (e) {
    parse_error = 'parse_failed: ' + e.message;
  }
}
if (parse_error) drafts = [{ format: 'manual', text: '（AI応答の取得/解析に失敗。手動で下書きを作成してください）' }];
const idempotency_key = ['repurpose', ctx.content_id, ctx.action_type].join('|');
return [{ json: {
  content_id: ctx.content_id,
  repurpose_drafts: drafts,
  draft_count: drafts.length,
  idempotency_key,
  state: 'WAITING_APPROVAL',
  published: false,
  draft_error: parse_error,
  note: 'dry-run。他媒体リパーパス下書きのみ生成。★自動投稿・自動展開はしない。人間が各媒体に手動で投稿する（CLAUDE.md 準拠）。'
} }];

// QAゲート不通過。リパーパス生成をスキップ。
const i = $input.first().json;
return [{ json: {
  content_id: i.content_id,
  skipped: true,
  qa_status: i.qa_status,
  state: 'SKIPPED_NOT_PASS',
  published: false,
  note: 'qa_status が PASS ではないためリパーパス下書き生成をスキップ。'
} }];
